```{ojs}
//| label: data-timeline
//| panel: center

// --- 1. Data ---
data = transpose(migration_data)
globalTotals = transpose(global_totals_data)
minYear = d3.min(globalTotals, d => d.year)
maxYear = d3.max(globalTotals, d => d.year)
mapWidth = Math.min(1100, width)

// --- 2. Timeline: big year, ticks every 5 years, native range slider ---
viewof selectedYear = {
  const ticks = d3.range(minYear, maxYear + 1, 5);
  if (ticks[ticks.length - 1] !== maxYear) ticks.push(maxYear);
  const pct = y => (y - minYear) / (maxYear - minYear) * 100;

  const form = html`
  <form style="width: ${mapWidth}px; max-width: 100%; margin: 20px auto 10px auto; font-family: sans-serif; color: #888;">
    <div style="font-size: 38px; font-weight: 300; letter-spacing: 2px; color: #e67e22; text-align: center; margin-bottom: 25px;">
      <output name="out">${maxYear}</output>
    </div>
    <div style="position: relative; width: 100%; height: 20px; font-size: 13px; margin-bottom: 2px;">
      ${ticks.map(y => html`<span style="position: absolute; left: ${pct(y)}%; transform: translateX(${y === minYear ? "-10%" : y === maxYear ? "-90%" : "-50%"});">${y}</span>`)}
    </div>
    <input type="range" name="range" min="${minYear}" max="${maxYear}" step="1" value="${maxYear}"
           style="width: 100%; cursor: pointer; accent-color: #e67e22; height: 4px;">
  </form>`;

  form.range.oninput = () => {
    form.value = form.range.valueAsNumber;
    form.out.value = form.range.valueAsNumber;
  };
  form.value = form.range.valueAsNumber;
  return form;
}

// --- 3. Aesthetics ---
trailOpacity = 0.25
particleSize = 0.7
particleSpeed = 0.002

// --- 4. Reactive accessors ---
currentMapData = data.filter(d => d.year === selectedYear)
trueGlobalTotal = globalTotals.find(d => d.year === selectedYear)?.true_total || 0

// --- 5. Global counter ---
html`<div style="text-align: center; font-family: sans-serif; font-size: 16px; color: #666; margin-top: 10px; margin-bottom: 20px;">
  Refugees & asylum-seekers recorded worldwide: <strong style="color: #2c3e50; font-size: 22px;">${d3.format(",")(trueGlobalTotal)}</strong> people<br>
  <span style="font-size: 11px; color: #888;">Only corridors above 5,000 people are drawn on the map.</span>
</div>`
```

